 static class Program {
  public static Color IconAccent {get{return Config!=null && Config.GreenIcons?Color.FromArgb(91,220,150):Color.FromArgb(180,186,192);}}
  public static void PlaceGlyph(Graphics g,Rectangle r,string name,Color color){
   if(name=="Home"){LucideIcons.Paint(g,"House",r,color);return;}if(name.IndexOf("Drive",StringComparison.OrdinalIgnoreCase)>=0||name.Contains(":")){LucideIcons.Paint(g,"HardDrive",r,color);return;}
   g.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.AntiAlias;using(var pen=new Pen(color,1.5f)){pen.StartCap=pen.EndCap=System.Drawing.Drawing2D.LineCap.Round;int x=r.X,y=r.Y;
    if(name=="Downloads"){g.DrawLine(pen,x+8,y+1,x+8,y+11);g.DrawLine(pen,x+4,y+7,x+8,y+11);g.DrawLine(pen,x+8,y+11,x+12,y+7);g.DrawLine(pen,x+2,y+15,x+14,y+15);}
    else if(name=="Desktop"){g.DrawRectangle(pen,x+1,y+2,14,10);g.DrawLine(pen,x+5,y+15,x+11,y+15);g.DrawLine(pen,x+8,y+12,x+8,y+15);}
    else if(name=="Documents"){g.DrawRectangle(pen,x+3,y+1,10,14);g.DrawLine(pen,x+5,y+6,x+11,y+6);g.DrawLine(pen,x+5,y+9,x+11,y+9);}
    else if(name=="OneDrive"){g.DrawArc(pen,x+2,y+5,9,8,160,190);g.DrawArc(pen,x+7,y+3,8,10,220,180);g.DrawLine(pen,x+3,y+13,x+13,y+13);}
    else FolderGlyph(g,r,color);
   }g.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.Default;
  }
  public static void FolderGlyph(Graphics g,Rectangle r,Color color){using(var b=new SolidBrush(color)){g.FillRectangle(b,r.X,r.Y+4,r.Width,r.Height-5);g.FillRectangle(b,r.X+1,r.Y+2,Math.Max(4,r.Width/2),4);}}
  public static bool Dragging,Busy; public static Settings Config;
  static string LogPath {get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Hedge","startup.log");}}
  public static void Log(string message){try{Directory.CreateDirectory(Path.GetDirectoryName(LogPath));File.AppendAllText(LogPath,DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss")+" "+message+Environment.NewLine);}catch{}}
  static void Report(Exception error){string details=error==null?"Unknown error":error.ToString();Log("ERROR: "+details);try{MessageBox.Show("Hedge encountered a problem:\n\n"+(error==null?"Unknown error":error.Message)+"\n\nDetails were saved to:\n"+LogPath,"Hedge error",MessageBoxButtons.OK,MessageBoxIcon.Error);}catch{try{NativeMessage("Hedge could not start. Details were saved to "+LogPath+"\n\n"+details,"Hedge error",0x10);}catch{}}}
  [DllImport("user32.dll",CharSet=CharSet.Unicode,EntryPoint="MessageBoxW")]static extern int NativeMessage(IntPtr parent,string text,string caption,uint type);
  static int NativeMessage(string text,string caption,uint type){return NativeMessage(IntPtr.Zero,text,caption,type);}
  [STAThread] static void Main(){
   Log("Starting Hedge 0.4.10");
   try{
    Application.SetUnhandledExceptionMode(UnhandledExceptionMode.CatchException);
    Application.ThreadException+=(sender,args)=>Report(args.Exception);
    AppDomain.CurrentDomain.UnhandledException+=(sender,args)=>{var e=args.ExceptionObject as Exception;if(e!=null)Report(e);else Log("Unhandled error: "+args.ExceptionObject);};
    bool created;using(var mutex=new System.Threading.Mutex(true,"Local\\Hedge.v1",out created)){
     if(!created){Log("Another instance is running.");MessageBox.Show("Hedge is already running. Use the blue screen-edge strip or the Hedge icon in the system tray to open a drawer.","Hedge",MessageBoxButtons.OK,MessageBoxIcon.Information);return;}
     DarkWindows.Enable();Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Config=Settings.Load();
     if(Config.Favorites==null)Config.Favorites=new List<string>();if(Config.LeftA==null)Config.LeftA=new List<string>();if(Config.LeftB==null)Config.LeftB=new List<string>();if(Config.RightA==null)Config.RightA=new List<string>();if(Config.RightB==null)Config.RightB=new List<string>();
     Log("Settings loaded; creating drawers.");var host=new Host();Log("Drawers created; showing the left drawer.");host.ShowInitial();if(Environment.GetCommandLineArgs().Contains("--visual-test")){host.SetupVisualFixture();var visualTimer=new Timer{Interval=8000};visualTimer.Tick+=(ss,ee)=>{visualTimer.Stop();try{host.CaptureVisualFixture();Log("VISUAL_TEST_OK");}catch(Exception e){Log("VISUAL_TEST_ERROR: "+e);}finally{visualTimer.Dispose();host.ExitThread();}};visualTimer.Start();}if(Environment.GetCommandLineArgs().Contains("--smoke-test")){var testTimer=new Timer{Interval=800};testTimer.Tick+=(ss,ee)=>{testTimer.Stop();try{host.SmokeTest();Log("UI_SMOKE_OK");}catch(Exception e){Log("UI_SMOKE_ERROR: "+e);}finally{testTimer.Dispose();host.ExitThread();}};testTimer.Start();}Application.Run(host);Log("Exit completed.");
    }
   }catch(Exception error){Report(error);}
  }
  public static Button Icon(string name,Action action,string tip){var b=new LucideButton{IconName=name,Width=32,Height=29,AutoSize=false,Margin=new Padding(0),FlatStyle=FlatStyle.Flat,BackColor=Color.FromArgb(32,35,41),ForeColor=Color.FromArgb(220,225,234),Cursor=Cursors.Hand};b.FlatAppearance.BorderSize=0;b.FlatAppearance.MouseOverBackColor=Color.FromArgb(48,55,53);b.Click+=(s,e)=>action();var tt=new ToolTip();tt.SetToolTip(b,tip);b.Disposed+=(s,e)=>tt.Dispose();return b;}
  public static ContextMenuStrip DarkMenu(){var menu=new ContextMenuStrip{BackColor=Color.FromArgb(37,40,47),ForeColor=Color.FromArgb(232,235,240),ShowImageMargin=false,Renderer=new ToolStripProfessionalRenderer(new DarkColors())};return menu;}
  public static Button Button(string text,Action action){var b=new Button{Text=text,AutoSize=true,Height=29,FlatStyle=FlatStyle.System};b.Click+=(s,e)=>action();return b;}
  public static void Theme(Control c){
   c.BackColor=Color.FromArgb(30,32,38);c.ForeColor=Color.FromArgb(230,233,240);
   var button=c as Button;if(button!=null){button.FlatStyle=FlatStyle.Flat;button.FlatAppearance.BorderSize=0;button.FlatAppearance.BorderColor=Color.FromArgb(62,67,79);button.FlatAppearance.MouseOverBackColor=Color.FromArgb(48,55,53);button.BackColor=Color.FromArgb(30,32,38);}
   var tb=c as TextBox;if(tb!=null){tb.BackColor=Color.FromArgb(42,46,55);tb.ForeColor=Color.White;tb.BorderStyle=BorderStyle.None;}
   var lv=c as ListView;if(lv!=null){lv.BackColor=Color.FromArgb(23,26,29);lv.ForeColor=Color.FromArgb(232,235,241);lv.GridLines=false;}
   var lb=c as ListBox;if(lb!=null){lb.BackColor=Color.FromArgb(30,33,36);lb.ForeColor=Color.FromArgb(230,233,240);lb.BorderStyle=BorderStyle.None;}
   foreach(Control child in c.Controls)Theme(child);
   var input=c as InputFrame;if(input!=null)input.ApplyTheme();
  }
  public static void Error(Exception e){MessageBox.Show(e.Message,"Hedge",MessageBoxButtons.OK,MessageBoxIcon.Warning);}
