  public InputFrame(TextBox box,bool isSearch){input=box;search=isSearch;Dock=DockStyle.Fill;Margin=new Padding(3,0,3,0);Padding=new Padding(search?34:10,6,10,5);DoubleBuffered=true;box.BorderStyle=BorderStyle.None;box.AutoSize=false;box.Dock=DockStyle.Fill;box.Visible=true;Controls.Add(box);if(search)box.HandleCreated+=(s,e)=>SendMessage(box.Handle,0x1501,IntPtr.Zero,"Find");box.GotFocus+=(s,e)=>Invalidate();box.LostFocus+=(s,e)=>Invalidate();Click+=(s,e)=>input.Focus();}
