 class Host:ApplicationContext {
  Drawer left,right;NotifyIcon tray;bool exiting;
  public Host(){left=new Drawer(true);right=new Drawer(false);tray=new NotifyIcon{Text="Hedge • left and right file drawers",Icon=Icon.ExtractAssociatedIcon(Application.ExecutablePath) ?? SystemIcons.Application,Visible=true};var menu=new ContextMenuStrip();menu.Items.Add("Open left",null,(s,e)=>left.Reveal());menu.Items.Add("Open right",null,(s,e)=>right.Reveal());menu.Items.Add("Settings",null,(s,e)=>EditSettings());menu.Items.Add("Exit",null,(s,e)=>ExitThread());tray.ContextMenuStrip=menu;tray.DoubleClick+=(s,e)=>left.Reveal();left.Show();right.Show();left.Collapse();right.Collapse();}
  public void ShowInitial(){left.Reveal();}
  public void SmokeTest(){left.SmokeTest();right.SmokeEdge();}
  public void SetupVisualFixture(){string root=Path.Combine(Path.GetTempPath(),"HedgeVisualFixture");Directory.CreateDirectory(root);Directory.CreateDirectory(Path.Combine(root,"Documents"));Directory.CreateDirectory(Path.Combine(root,"Pictures"));File.WriteAllText(Path.Combine(root,"notes.txt"),"Hedge visual fixture");left.PrepareVisual(root);}
  public void CaptureVisualFixture(){left.RenderVisual(Environment.GetEnvironmentVariable("HEDGE_VISUAL_OUTPUT"));}
  void EditSettings(){using(var f=new Form{Text="Hedge settings",Size=new Size(450,430),StartPosition=FormStartPosition.CenterScreen,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false}){var table=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(18),ColumnCount=2,RowCount=10};table.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,60));table.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,40));f.Controls.Add(table);var c=Program.Config;
  var width=Number(table,"Drawer width (pixels)",c.Width,420,1400);var pos=Number(table,"Hotspot position (% down edge)",c.SpotPercent,5,95);var height=Number(table,"Hotspot height (pixels)",c.SpotHeight,30,600);var delay=Number(table,"Hover delay (milliseconds)",c.Delay,0,2000);var monitor=Number(table,"Monitor (1 = first display)",c.Monitor+1,1,Screen.AllScreens.Length);var hidden=new CheckBox{Text="Show hidden files",Checked=c.Hidden,AutoSize=true};table.Controls.Add(hidden);table.SetColumnSpan(hidden,2);table.Controls.Add(new Label{Text="Edge strips stay visible. Drag files onto a strip to open its drawer.",AutoSize=true});table.SetColumnSpan(table.Controls[table.Controls.Count-1],2);
  table.Controls.Add(new Label{Text="Folder and shortcut icons",AutoSize=true,Anchor=AnchorStyles.Left});var iconColor=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Dock=DockStyle.Fill};iconColor.Items.AddRange(new object[]{"Green","Gray"});iconColor.SelectedIndex=c.GreenIcons?0:1;table.Controls.Add(iconColor);
  table.Controls.Add(Program.Button("Save",()=>{c.GreenIcons=iconColor.SelectedIndex==0;c.Width=(int)width.Value;c.SpotPercent=(int)pos.Value;c.SpotHeight=(int)height.Value;c.Delay=(int)delay.Value;c.Monitor=(int)monitor.Value-1;c.Hidden=hidden.Checked;left.Position();right.Position();left.RefreshAll();right.RefreshAll();Save();f.Close();}));f.ShowDialog();}}
  NumericUpDown Number(TableLayoutPanel t,string label,int value,int min,int max){t.Controls.Add(new Label{Text=label,AutoSize=true,Anchor=AnchorStyles.Left});var n=new NumericUpDown{Minimum=min,Maximum=max,Value=Math.Max(min,Math.Min(max,value)),Dock=DockStyle.Fill};t.Controls.Add(n);return n;}
  void Save(){try{left.Store();right.Store();Program.Config.Save();}catch(Exception e){Program.Error(e);}}
  protected override void ExitThreadCore(){if(exiting)return;if(Program.Busy||Program.Dragging){MessageBox.Show("Wait for the current file operation to finish before exiting.","Hedge");return;}exiting=true;Save();tray.Visible=false;tray.Dispose();left.Shutdown();right.Shutdown();base.ExitThreadCore();}
 }
 class Drawer:Form {
  bool left,expanded,closing,pinned;int drawerWidth;DateTime hover=DateTime.MinValue,away=DateTime.MinValue;
  SplitContainer split;TabPane a,b;Form strip;Timer timer;Button pin,splitButton,orientationButton;public Drawer(bool isLeft){left=isLeft;drawerWidth=(isLeft?Program.Config.LeftWidth:Program.Config.RightWidth);if(drawerWidth<320)drawerWidth=Program.Config.Width;Text="Hedge • "+(left?"Left":"Right");FormBorderStyle=FormBorderStyle.None;ShowInTaskbar=false;TopMost=true;BackColor=Color.FromArgb(228,232,238);Padding=new Padding(2);Font=new Font("Segoe UI",10);
   var header=new FlowLayoutPanel{Dock=DockStyle.Top,Height=32,Padding=new Padding(2,1,0,0),WrapContents=false};pin=Program.Icon("Pin",()=>{pinned=!pinned;UpdateToolbar();},"Pin drawer open");header.Controls.Add(pin);splitButton=Program.Icon("Columns2",()=>{split.Panel2Collapsed=!split.Panel2Collapsed;UpdateToolbar();},"One or two views");orientationButton=Program.Icon("Rows2",()=>{split.Orientation=split.Orientation==Orientation.Horizontal?Orientation.Vertical:Orientation.Horizontal;UpdateToolbar();},"Stack views or place side by side");header.Controls.Add(splitButton);header.Controls.Add(orientationButton);header.Controls.Add(Program.Icon(left?"PanelLeftClose":"PanelRightClose",()=>Collapse(),"Collapse drawer"));
   split=new SplitContainer{Dock=DockStyle.Fill,Orientation=Orientation.Horizontal,Size=new Size(700,650),SplitterWidth=6,Panel1MinSize=150,Panel2MinSize=150,SplitterDistance=320};a=new TabPane(left?Program.Config.LeftA:Program.Config.RightA);b=new TabPane(left?Program.Config.LeftB:Program.Config.RightB);split.Panel1.Controls.Add(a);split.Panel2.Controls.Add(b);split.Panel2Collapsed=!(left?Program.Config.LeftSplit:Program.Config.RightSplit);Controls.Add(split);Controls.Add(header);var edge=new Panel{Dock=left?DockStyle.Right:DockStyle.Left,Width=7,Cursor=Cursors.SizeWE,BackColor=Color.FromArgb(43,47,56)};Controls.Add(edge);edge.BringToFront();bool resizing=false;edge.MouseDown+=(ss,ee)=>{if(ee.Button==MouseButtons.Left){resizing=true;edge.Capture=true;}};edge.MouseMove+=(ss,ee)=>{if(!resizing)return;var r=Screen.FromControl(this).WorkingArea;int desired=left?Cursor.Position.X-r.Left:r.Right-Cursor.Position.X;drawerWidth=Math.Max(360,Math.Min(r.Width,desired));Position();};edge.MouseUp+=(ss,ee)=>{if(resizing){resizing=false;edge.Capture=false;if(left)Program.Config.LeftWidth=drawerWidth;else Program.Config.RightWidth=drawerWidth;}};Program.Theme(this);UpdateToolbar();
   strip=new EdgeStrip{FormBorderStyle=FormBorderStyle.None,ShowInTaskbar=false,TopMost=true,BackColor=Color.FromArgb(93,105,103),Opacity=.6,AllowDrop=true};strip.Cursor=Cursors.Hand;strip.MouseEnter+=(s,e)=>hover=DateTime.UtcNow;strip.MouseLeave+=(s,e)=>hover=DateTime.MinValue;strip.Click+=(s,e)=>Reveal();strip.DragEnter+=(s,e)=>{if(e.Data.GetDataPresent(DataFormats.FileDrop)){e.Effect=DragDropEffects.Copy;Reveal();}};
   timer=new Timer{Interval=40};timer.Tick+=(s,e)=>TickEdge();timer.Start();SystemEventsHook();Position();strip.Show();FormClosing+=(s,e)=>{if(!closing){e.Cancel=true;Collapse();}};
  }
  void UpdateToolbar(){if(split==null)return;pin.BackColor=pinned?Color.FromArgb(36,75,62):Color.FromArgb(30,32,38);splitButton.BackColor=!split.Panel2Collapsed?Color.FromArgb(36,75,62):Color.FromArgb(30,32,38);orientationButton.BackColor=split.Orientation==Orientation.Vertical?Color.FromArgb(36,75,62):Color.FromArgb(30,32,38);pin.Invalidate();splitButton.Invalidate();orientationButton.Invalidate();}
  void SystemEventsHook(){Microsoft.Win32.SystemEvents.DisplaySettingsChanged+=DisplayChanged;}
  void DisplayChanged(object s,EventArgs e){if(IsHandleCreated&&!IsDisposed)BeginInvoke((Action)Position);}
  public void Position(){var screens=Screen.AllScreens;var screen=screens[Math.Max(0,Math.Min(Program.Config.Monitor,screens.Length-1))];var r=screen.WorkingArea;int w=Math.Min(Math.Max(360,drawerWidth),r.Width);Bounds=new Rectangle(left?r.Left:r.Right-w,r.Top,w,r.Height);int h=Math.Min(Program.Config.SpotHeight,r.Height);int y=r.Top+(int)((r.Height-h)*Program.Config.SpotPercent/100.0);((EdgeStrip)strip).SetEdgeBounds(new Rectangle(left?r.Left:r.Right-4,y,4,h));}
  public void SmokeEdge(){((EdgeStrip)strip).VerifyEdge();}
  public void PrepareVisual(string path){pinned=true;drawerWidth=700;Position();Reveal();split.Panel2Collapsed=false;split.Orientation=Orientation.Horizontal;a.OpenVisual(path);b.OpenVisual(path);a.VerifyVisual();b.VerifyVisual();}
  public void RenderVisual(string path){if(String.IsNullOrEmpty(path))throw new Exception("Visual output path is missing");a.SelectVisualRow();b.SelectVisualRow();using(var bitmap=new Bitmap(Width,Height)){DrawToBitmap(bitmap,new Rectangle(0,0,Width,Height));bitmap.Save(path,System.Drawing.Imaging.ImageFormat.Png);}}
  public void SmokeTest(){a.SmokeTest();int old=drawerWidth;SetWidth(old+40);Position();if(drawerWidth!=old+40)throw new Exception("Width did not change");SetWidth(old);Position();}
  public void SetWidth(int width){drawerWidth=width;if(left)Program.Config.LeftWidth=width;else Program.Config.RightWidth=width;}
  void TickEdge(){if(!expanded){if(hover!=DateTime.MinValue&&(DateTime.UtcNow-hover).TotalMilliseconds>=Program.Config.Delay)Reveal();return;}if(pinned||Program.Dragging||Program.Busy||ContainsFocus||Bounds.Contains(Cursor.Position)){away=DateTime.MinValue;return;}if(away==DateTime.MinValue)away=DateTime.UtcNow;if((DateTime.UtcNow-away).TotalMilliseconds>700)Collapse();}
  public void Reveal(){if(expanded)return;expanded=true;away=DateTime.MinValue;Position();Show();BringToFront();strip.Hide();}
  public void Collapse(){expanded=false;Hide();hover=DateTime.MinValue;strip.Show();Position();}
  public void RefreshAll(){a.RefreshActive();b.RefreshActive();}
  public void Store(){if(left){Program.Config.LeftA=a.Paths();Program.Config.LeftB=b.Paths();Program.Config.LeftSplit=!split.Panel2Collapsed;}else{Program.Config.RightA=a.Paths();Program.Config.RightB=b.Paths();Program.Config.RightSplit=!split.Panel2Collapsed;}}
  public void Shutdown(){closing=true;Microsoft.Win32.SystemEvents.DisplaySettingsChanged-=DisplayChanged;timer.Stop();timer.Dispose();strip.Close();strip.Dispose();Close();Dispose();}
 }
